package main

import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1000003

func modPow(base int64, exp int) int64 {
	result := int64(1)
	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}
	return result
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var n int
	fmt.Fscan(in, &n)

	if n == 0 {
		fmt.Fprintln(out, 1)
	} else {
		fmt.Fprintln(out, modPow(3, n-1))
	}
}

