import (
	"bufio"
	"fmt"
	"os"
)

const mod int64 = 1000003

func main() {
	in := bufio.NewReader(os.Stdin)

	var n int
	fmt.Fscan(in, &n)

	if n == 0 {
		fmt.Println(1)
		return
	}

	var result, base int64 = 1, 3
	exp := n - 1

	for exp > 0 {
		if exp&1 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp >>= 1
	}

	fmt.Println(result)
}
